# Helper to check if a string contains a weak algorithm (case-insensitive)
contains_weak_algorithm(val) {
    val.ir_type == "String"
    lower_val := lower(val.value)
    some weak_alg in weak_algorithms
    contains(lower_val, lower(weak_alg))
}

