check_hash_elements_for_weak_value(hash_val) {
    some kv in hash_val.value
    kv.value.ir_type == "String"
    contains_weak_algorithm(kv.value)
}

# Check any Value type (String, Hash, Array) for weak cryptographic configurations
check_value_for_weak_crypto(val) {
    val.ir_type == "String"
    contains_weak_algorithm(val)
} else {
    val.ir_type == "Hash"
    check_hash_elements_for_weak_value(val)
} else {
    val.ir_type == "Array"
    some element in val.value
    check_value_for_weak_crypto(element)
