package glitch

import data.glitch_lib

# Define weak cryptographic algorithms, hashing methods, and cipher suites
weak_crypto_patterns := {"des", "3des", "triple des", "tdea", "rc2", "rc4", "blowfish", "aes-128", "rsa-1024", "ecb", "md5", "sha1", "hmac-md5", "hmac-sha1", "md5_crypt", "tls_rsa_with_aes_128"}

# Helper function to check if a string contains a weak crypto pattern
contains_weak_crypto(str) {
    regex.match(sprintf("(?i).*\\b(%s)\\b.*", [concat("|", weak_crypto_patterns)]), str)
}

# Helper to check if an Attribute name or value indicates weakness (handles specific logic for Ansible/Chef)
check_attr(attr) {
    attr.ir_type == "Attribute"
    # Check if attribute name or value is weak
    contains_weak_crypto(attr.name)
} else {
    attr.ir_type == "Attribute"
    attr.value.ir_type == "String"
    contains_weak_crypto(attr.value.value)
} else {
    attr.ir_type == "Attribute"
    attr.value.ir_type == "Access"
    # Handle variable references like jenkins_user_data['password_md5']
    # Check if the access key (right side) indicates a weak algo (e.g., password_md5)
    access_right := attr.value.right
    access_right.ir_type == "String"
    contains_weak_crypto(access_right.value)
}

# Helper to check Variables (e.g., Chef Variables inside ConditionalStatements)
check_var(var) {
    var.ir_type == "Variable"
    var.value.ir_type == "String"
    contains_weak_crypto(var.value.value)
}

# Rule 1: Direct detection in Attributes (Ansible, Chef, Puppet)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    all_attrs := glitch_lib.all_attributes(parent)
    attr := all_attrs[_]
    check_attr(attr)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of a Broken or Risky Cryptographic Algorithm - The application uses a broken or risky cryptographic algorithm. (CWE-327)"
    }
}

